730: func (m *namespaceManager) Run(ctx context.Context) {
731: 	ticker := time.NewTicker(5 * time.Minute)
732: 	defer ticker.Stop()
733: 
734: 	for {
735: 		select {
736: 		case <-ctx.Done():
737: 			return
738: 		case t := <-ticker.C:
739: 			// periodically remove any namespaces which haven't been seen in flows
740: 			// for the last hour
741: 			m.mu.Lock()
742: 			for key, record := range m.namespaces {
743: 				if record.added.Add(time.Hour).After(t) {
744: 					delete(m.namespaces, key)
745: 				}
746: 			}
747: 			m.mu.Unlock()
748: 		}
749: 	}
750: }
