752: func (m *namespaceManager) GetNamespaces() []*observerpb.Namespace {
753: 	m.mu.RLock()
754: 	namespaces := make([]*observerpb.Namespace, 0, len(m.namespaces))
755: 	for _, ns := range m.namespaces {
756: 		namespaces = append(namespaces, ns.namespace)
757: 	}
758: 	m.mu.RUnlock()
759: 
760: 	slices.SortFunc(namespaces, func(a, b *observerpb.Namespace) bool {
761: 		if a.Cluster != b.Cluster {
762: 			return a.Cluster < b.Cluster
763: 		}
764: 		return a.Namespace < b.Namespace
765: 	})
766: 	return namespaces
767: }
