769: func (m *namespaceManager) AddNamespace(ns *observerpb.Namespace) {
770: 	m.mu.Lock()
771: 	key := ns.GetCluster() + "/" + ns.GetNamespace()
772: 	m.namespaces[key] = namespaceRecord{namespace: ns, added: time.Now()}
773: 	m.mu.Unlock()
774: }

